/** Exact multiway overlap; missing coverage, source families and frozen validation remain distinct. */
final class StudyCohortOverlap implements StudyOperationExecutor {
    static final String CAVEAT="Overlap is descriptive and depends on coverage, sample size, assay, power and the declared testing families. Missing/unestimable features are not negative evidence. Dataset sets and distinct declared cohort IDs do not establish independence. A no-shared-hit alert calls for review and prespecified sensitivity, not automatic exclusion or a new primary cohort set. Direction and full-family/source declarations require scientific appraisal.";
    @Override public Result execute(Context c)throws Exception {
        Files.createDirectories(c.outputDirectory());var analysis=StudyResultTables.analysis(c);var p=StudyCohortPolicy.overlap(map(analysis.get("cohort_overlap")));var details=new LinkedHashMap<String,Object>();details.put("required_manuscript_caveat",CAVEAT);
        if(!Boolean.TRUE.equals(p.get("enabled")))return finish(c,p,details,true,false,"Cohort overlap disabled by protocol");
        var sources=StudyCohortResults.sources(c);if(sources.size()<2)return finish(c,p,details,false,false,"Multiway overlap needs at least two completed, producer-verified cohort result tables; a pooled or pairwise summary cannot reconstruct missing tested universes");
        List<String> ids=List.copyOf(sources.keySet());details.put("set_order",ids);if(ids.size()>integer(p,"maximum_sets"))return finish(c,p,details,false,false,"Complete cohort scope exceeds maximum_sets; no cohort subset was selected");String method=StudyCohortResults.method(c);
        var originalSources=new LinkedHashMap<String,Object>();for(var entry:sources.entrySet())originalSources.put(entry.getKey(),Map.of("artifact",c.project().relativize(entry.getValue()).toString().replace('\\','/'),"sha256",FollowupSupport.hash(entry.getValue())));details.put("original_sources",originalSources);details.put("registered_common_family_policy",map(analysis.get("harmonization")).getOrDefault("common_universe","none"));
        sources=StudyResultTables.universe(c,sources,"cohort-overlap-family-inputs");
        var tables=new LinkedHashMap<String,StudyCohortResults.Table>();for(String id:ids)tables.put(id,StudyCohortResults.read(sources.get(id),method));
        var union=new TreeSet<String>();Set<String> common=null;for(var t:tables.values()){var eligible=new TreeSet<>(t.adjusted().keySet());union.addAll(t.rows().keySet());if(common==null)common=eligible;else common.retainAll(eligible);}if(common==null)common=Set.of();Set<String> universe="intersection".equals(p.get("universe"))?new TreeSet<>(common):union;
        details.put("observed_union_features",union.size());details.put("common_estimable_features",common.size());details.put("analysis_universe",p.get("universe"));details.put("universe_features",universe.size());
        if(union.size()>integer(p,"maximum_features")||(long)union.size()*ids.size()>integer(p,"maximum_cells"))return finish(c,p,details,false,false,"Complete cohort membership exceeds its feature/cell bounds; no top-hit truncation was applied");
        var datasetMap=new LinkedHashMap<String,Map<String,Object>>();for(Object raw:list(c.study().get("datasets"))){var d=map(raw);datasetMap.put(text(d.get("id")),d);}var roles=map(c.operation().get("roles"));if(roles.isEmpty())for(Object raw:list(c.study().get("hypotheses")))if(c.operation().get("hypothesis").equals(map(raw).get("id")))roles=map(map(raw).get("inputs"));
        var namespaces=new TreeSet<String>();var species=new TreeSet<String>();var builds=new TreeSet<String>();
        for(String id:ids){var d=datasetMap.getOrDefault(id,Map.of());String namespace=text(d.get("feature_id_type"));if(!namespace.isBlank()&&!Set.of("auto","unknown").contains(namespace))namespaces.add(namespace);String organism=StudyPoolingAudit.canonical("species",text(d.get("species")));if(!organism.isBlank())species.add(organism);if(Set.of("gwas","genomics").contains(text(d.get("type")))){String build=text(d.get("genome_build"));if(!build.isBlank())builds.add(StudyPoolingAudit.canonical("genome_build",build));}}
        details.put("declared_feature_namespaces",List.copyOf(namespaces));details.put("declared_species",List.copyOf(species));details.put("variant_genome_builds",List.copyOf(builds));details.put("identity_comparability","Source declarations and exact identifiers; assay/version equivalence is not independently certified");
        if(namespaces.size()>1||species.size()>1||builds.size()>1)return finish(c,p,details,false,false,"Known feature namespace, species or variant-build incompatibility prevents identifier-based cohort overlap; supply an explicit harmonized feature universe or separate compatible blocks");
        Set<String> discovery=new LinkedHashSet<>(list(roles.get("discovery")).stream().map(StudyPublicEvidence::text).filter(ids::contains).toList()),validation=new LinkedHashSet<>(list(roles.get("replication")).stream().map(StudyPublicEvidence::text).filter(ids::contains).toList());if(!java.util.Collections.disjoint(discovery,validation))return finish(c,p,details,false,false,"Discovery and validation dataset roles overlap");
        String validationFamily=text(p.get("validation_family"));if(validationFamily.equals("analysis"))validationFamily=text(map(analysis.get("replication")).getOrDefault("adjustment_scope","all_results"));String comparison=text(p.get("threshold_comparison"));if(comparison.equals("analysis"))comparison=text(map(analysis.get("replication")).getOrDefault("threshold_comparison","less_than"));boolean strict=comparison.equals("less_than");double alpha=p.containsKey("alpha")?((Number)p.get("alpha")).doubleValue():StudyCohortResults.alpha(c);double discoveryAlpha=((Number)analysis.getOrDefault("discovery_alpha",alpha)).doubleValue(),validationAlpha=((Number)analysis.getOrDefault("replication_alpha",alpha)).doubleValue();
        details.put("validation_family",validationFamily);details.put("direction_rule",p.get("direction"));details.put("threshold_comparison",comparison);details.put("discovery_alpha",discoveryAlpha);details.put("validation_alpha",validationAlpha);details.put("other_alpha",alpha);
        boolean needsReference=validationFamily.equals("discovery_subset")||"require_discovery".equals(p.get("direction"));StudyCohortResults.Table reference=null;
        if(discovery.size()==1)reference=tables.get(discovery.iterator().next());else if(discovery.size()>1){Path pool=StudyResultTables.artifact(c,"discovery_meta_analysis","discovery-results.tsv");if(pool!=null)reference=StudyCohortResults.read(pool,method);}
        if(needsReference&&(reference==null||validation.isEmpty()))return finish(c,p,details,false,false,"Reduced validation/direction needs a declared discovery source and validation cohorts; multiple discovery sources need their completed discovery-only pool");
        if(needsReference&&validationFamily.equals("discovery_subset")&&!"intersection".equals(p.get("universe")))return finish(c,p,details,false,false,"Reduced validation uses a predefined common tested universe; register cohort_overlap.universe: intersection");
        if(reference!=null){details.put("discovery_reference",StudyCohortResults.receipt(c,reference));details.put("discovery_reference_complete_in_universe",reference.adjusted().keySet().containsAll(universe));}
        if(needsReference&&!reference.adjusted().keySet().containsAll(universe))return finish(c,p,details,false,false,"The discovery reference does not cover the complete registered common universe; selected-only summaries cannot establish an omitted candidate is negative");
        var frozen=new TreeSet<String>();if(reference!=null)for(String feature:universe)if(significant(reference.adjusted().getOrDefault(feature,Double.NaN),discoveryAlpha,strict))frozen.add(feature);
        details.put("frozen_discovery_features",reference==null?"NA":frozen.size());if(reference!=null)details.put("discovery_reference",StudyCohortResults.receipt(c,reference));
        var q=new LinkedHashMap<String,Map<String,Double>>();var familyRows=new ArrayList<String[]>();for(String id:ids){var t=tables.get(id);Map<String,Double> adjusted=t.adjusted();boolean reduced=validation.contains(id)&&validationFamily.equals("discovery_subset");if(reduced){var family=new LinkedHashMap<String,Double>();for(String feature:frozen){var row=t.rows().get(feature);if(row!=null&&row.estimable())family.put(feature,row.p());}if(family.size()!=frozen.size())return finish(c,p,details,false,false,"A reduced validation family is incomplete; missing tests are not assigned P=1 or removed from its denominator");adjusted=StudyCohortResults.adjust(family,method);}q.put(id,adjusted);familyRows.add(new String[]{id,role(id,discovery,validation),reduced?"frozen_discovery_subset":"complete_observed_source_family",String.valueOf(adjusted.size()),reduced?method:t.adjustment(),String.valueOf(validation.contains(id)?validationAlpha:discovery.contains(id)?discoveryAlpha:alpha),comparison,t.sha256(),t.family().isEmpty()?"observed_source_universe_not_independently_certified":text(t.family().getOrDefault("coverage","unknown"))});}
        FollowupSupport.table(c.outputDirectory().resolve("cohort-overlap-families.tsv"),List.of("set_id","role","selection_family","testing_denominator","adjustment","alpha","threshold_comparison","source_sha256","source_coverage"),familyRows);
        var sourceReceipts=new LinkedHashMap<String,Object>();for(var entry:tables.entrySet())sourceReceipts.put(entry.getKey(),StudyCohortResults.receipt(c,entry.getValue()));details.put("sources",sourceReceipts);
        var selected=new LinkedHashMap<String,Set<String>>();for(String id:ids)selected.put(id,new TreeSet<>());var patterns=new TreeMap<String,long[]>();long[] degree=new long[ids.size()+1];var featureRows=new ArrayList<String[]>();
        Path membership=c.outputDirectory().resolve("cohort-overlap-membership.tsv");try(var writer=Files.newBufferedWriter(membership)){
            writer.write("feature_id\tset_id\tcohort\trole\tin_universe\tsource_estimable\tin_selection_family\tp_value\tadjusted_p\tbeta\tdiscovery_candidate\tsame_sign_reference\tselected\tstatus\n");
            for(String feature:union){StringBuilder signature=new StringBuilder();int tested=0,chosen=0,positive=0,negative=0,unknownDirection=0;var chosenCohorts=new TreeSet<String>();boolean unknownCohort=false;boolean included=universe.contains(feature);
                for(String id:ids){var row=tables.get(id).rows().get(feature);boolean estimable=row!=null&&row.estimable(),inFamily=q.get(id).containsKey(feature);double adjusted=q.get(id).getOrDefault(feature,Double.NaN);String same="unavailable";if(reference!=null&&reference.rows().containsKey(feature)&&row!=null){double a=reference.rows().get(feature).beta(),b=row.beta();if(Double.isFinite(a)&&Double.isFinite(b)&&a!=0&&b!=0)same=String.valueOf(Math.signum(a)==Math.signum(b));}
                    boolean hit=included&&significant(adjusted,validation.contains(id)?validationAlpha:discovery.contains(id)?discoveryAlpha:alpha,strict);if(validation.contains(id)&&"require_discovery".equals(p.get("direction")))hit&=same.equals("true");String cohort=text(datasetMap.getOrDefault(id,Map.of()).get("cohort"));if(hit){selected.get(id).add(feature);chosen++;if(cohort.isBlank())unknownCohort=true;else chosenCohorts.add(cohort);if(row.beta()>0)positive++;else if(row.beta()<0)negative++;else unknownDirection++;}if(estimable)tested++;signature.append(hit?'1':'0');String status=!included?"outside_overlap_universe":!estimable?"not_estimable_or_unobserved":!inFamily?"outside_frozen_discovery_family":hit?"selected":"tested_not_selected";
                    writer.write(String.join("\t",feature,id,cohort,role(id,discovery,validation),String.valueOf(included),String.valueOf(estimable),String.valueOf(inFamily),value(row==null?Double.NaN:row.p()),value(adjusted),value(row==null?Double.NaN:row.beta()),reference==null||!reference.adjusted().containsKey(feature)?"NA":String.valueOf(frozen.contains(feature)),same,String.valueOf(hit),status)+"\n");
                }
                if(included){long[] counts=patterns.computeIfAbsent(signature.toString(),ignored->new long[2]);counts[0]++;if(tested==ids.size())counts[1]++;degree[chosen]++;featureRows.add(new String[]{feature,signature.toString(),String.valueOf(tested),String.valueOf(chosen),unknownCohort?"NA":String.valueOf(chosenCohorts.size()),String.join(";",chosenCohorts),unknownDirection>0?"unavailable_or_zero_selected_effect_directions":positive>0&&negative>0?"opposite_selected_effect_directions":chosen>0?"no_observed_opposite_selected_directions":"no_selected_effects",reference==null||!reference.adjusted().containsKey(feature)?"NA":String.valueOf(frozen.contains(feature))});}
            }
        }
        FollowupSupport.table(c.outputDirectory().resolve("cohort-overlap-features.tsv"),List.of("feature_id","selected_pattern","estimable_sets","selected_sets","selected_declared_cohorts","selected_cohort_ids","direction_context","discovery_candidate"),featureRows);
        var patternRows=new ArrayList<String[]>();for(var entry:patterns.entrySet())patternRows.add(new String[]{entry.getKey(),String.valueOf(entry.getValue()[0]),String.valueOf(entry.getValue()[1]),String.valueOf(entry.getValue()[0]-entry.getValue()[1])});FollowupSupport.table(c.outputDirectory().resolve("cohort-overlap-patterns.tsv"),List.of("selected_pattern","features","all_sets_estimable","partial_coverage_features"),patternRows);
        var degreeRows=new ArrayList<String[]>();for(int k=0;k<degree.length;k++){long atLeast=0;for(int j=k;j<degree.length;j++)atLeast+=degree[j];degreeRows.add(new String[]{String.valueOf(k),String.valueOf(degree[k]),String.valueOf(atLeast),String.valueOf(universe.size())});}FollowupSupport.table(c.outputDirectory().resolve("cohort-overlap-degree.tsv"),List.of("selected_sets","exact_features","at_least_features","universe_features"),degreeRows);
        details.put("selected_union_features",universe.size()-degree[0]);details.put("all_sets_selected_features",degree[ids.size()]);details.put("observed_patterns",patterns.size());details.put("zero_overlap_alerts",alerts(p,ids,datasetMap,tables,selected));details.put("alert_assessment_complete",true);plot(c,p,ids,selected,patterns,details);
        return finish(c,p,details,true,true,"Recorded exact multiway membership, coverage, testing families, direction and bounded Venn/UpSet displays; primary cohort set unchanged");
    }
    private static List<Object> alerts(Map<String,Object> p,List<String> ids,Map<String,Map<String,Object>> datasets,Map<String,StudyCohortResults.Table> tables,Map<String,Set<String>> selected){var cohorts=new TreeMap<String,Set<String>>();for(String id:ids){String name=text(datasets.getOrDefault(id,Map.of()).get("cohort"));if(!name.isBlank())cohorts.computeIfAbsent(name,key->new TreeSet<>()).add(id);}var result=new ArrayList<Object>();if(!Boolean.TRUE.equals(p.get("zero_overlap_alert")))return result;
        for(var entry:cohorts.entrySet()){var own=new TreeSet<String>();var other=new TreeSet<String>();var ownTested=new TreeSet<String>();var otherTested=new TreeSet<String>();for(String id:ids)if(entry.getValue().contains(id)){own.addAll(selected.get(id));ownTested.addAll(tables.get(id).adjusted().keySet());}else{other.addAll(selected.get(id));otherTested.addAll(tables.get(id).adjusted().keySet());}var sharedTested=new TreeSet<>(ownTested);sharedTested.retainAll(otherTested);var eligibleOwn=new TreeSet<>(own);eligibleOwn.retainAll(sharedTested);var eligibleOther=new TreeSet<>(other);eligibleOther.retainAll(sharedTested);var overlap=new TreeSet<>(eligibleOwn);overlap.retainAll(eligibleOther);boolean alert=sharedTested.size()>=integer(p,"minimum_shared_tested")&&eligibleOwn.size()>=integer(p,"minimum_selected_features")&&!eligibleOther.isEmpty()&&overlap.isEmpty();result.add(Map.of("cohort",entry.getKey(),"datasets",List.copyOf(entry.getValue()),"shared_observed_tested_features",sharedTested.size(),"selected_own_shared",eligibleOwn.size(),"selected_other_shared",eligibleOther.size(),"shared_selected_features",overlap.size(),"alert",alert,"interpretation",alert?"No shared selected features in the observed shared tested universe; review power/coverage/assay and a registered omission, without automatic exclusion":"No qualifying zero-overlap alert; absent alerts do not establish comparability or independence"));}return result;}
    static void plot(Context c,Map<String,Object> p,List<String> ids,Map<String,Set<String>> selected,Map<String,long[]> patterns,Map<String,Object> details)throws IOException{var ordered=patterns.entrySet().stream().filter(e->e.getKey().contains("1")).sorted(java.util.Comparator.<Map.Entry<String,long[]>>comparingLong(e->e.getValue()[0]).reversed().thenComparing(Map.Entry::getKey)).toList();details.put("nonempty_patterns",ordered.size());if(ordered.isEmpty()){details.put("plot_disposition","No selected features; complete zero-count membership and testing universes retained");return;}int limit=Math.min(ordered.size(),integer(p,"plot_patterns"));var intersections=new ArrayList<DiagramPlots.SetIntersection>();for(var entry:ordered.subList(0,limit)){var bits=new ArrayList<Boolean>();for(char bit:entry.getKey().toCharArray())bits.add(bit=='1');intersections.add(new DiagramPlots.SetIntersection(bits,entry.getValue()[0]));}String caption="Showing "+limit+" of "+ordered.size()+" nonempty exclusive patterns; complete pattern table and tested coverage retained";var plot=DiagramPlots.upset(new DiagramPlots.UpSetData(ids,ids.stream().map(id->(long)selected.get(id).size()).toList(),intersections,caption),PlotOptions.builder().size(Math.max(1050,480+limit*25),430+ids.size()*24).title("Cohort overlap: exclusive selected-set intersections").build());plot.save(c.outputDirectory().resolve("cohort-overlap-upset.png"));plot.save(c.outputDirectory().resolve("cohort-overlap-upset.pdf"));details.put("displayed_patterns",limit);details.put("plot_disposition",caption);
        if(ids.size()==2){var v=DiagramPlots.venn(new DiagramPlots.VennData(ids.get(0),ids.get(1),(int)count(patterns,"10"),(int)count(patterns,"11"),(int)count(patterns,"01")),PlotOptions.builder().size(850,620).title("Selected-set overlap in the declared universe").build());v.save(c.outputDirectory().resolve("cohort-overlap-venn.png"));v.save(c.outputDirectory().resolve("cohort-overlap-venn.pdf"));}
        if(ids.size()==3){var v=DiagramPlots.venn(new DiagramPlots.ThreeSetVennData(ids,List.of("100","010","001","110","101","011","111").stream().map(key->count(patterns,key)).toList()),PlotOptions.builder().size(900,730).title("Selected-set overlap: exclusive counts").build());v.save(c.outputDirectory().resolve("cohort-overlap-venn.png"));v.save(c.outputDirectory().resolve("cohort-overlap-venn.pdf"));}
    }
    private static long count(Map<String,long[]> p,String key){return p.containsKey(key)?p.get(key)[0]:0;}
    private static boolean significant(double q,double a,boolean strict){return Double.isFinite(q)&&(strict?q<a:q<=a);}
    private static String role(String id,Set<String> discovery,Set<String> validation){return discovery.contains(id)?"discovery":validation.contains(id)?"validation":"other";}
    private static int integer(Map<String,Object> p,String key){return ((Number)p.get(key)).intValue();}
    private static String value(double n){return Double.isFinite(n)?String.valueOf(n):"NA";}
    private static Result finish(Context c,Map<String,Object> p,Map<String,Object> details,boolean complete,boolean performed,String reason)throws IOException{details.put("method_report",Map.of("performed",performed,"operation","cohort_overlap","method","Exact exclusive set membership with coverage-aware descriptive Venn/UpSet","parameters",p,"software","JLinAlg "+JLinAlgCli.version(),"references",List.of("https://doi.org/10.1109/TVCG.2014.2346248")));details.put("interpretation",reason);if(!complete)details.put("needs",List.of(StudyNeed.review("cohort-overlap:"+c.operation().get("hypothesis"),"Resolve the declared multiway cohort overlap inputs",reason,true).document()));write(c.outputDirectory().resolve("cohort-overlap.yaml"),details);var outputs=new ArrayList<String>();try(var files=Files.walk(c.outputDirectory())){for(Path file:files.filter(Files::isRegularFile).sorted().toList())outputs.add(c.outputDirectory().relativize(file).toString().replace('\\','/'));}return new Result(complete?State.COMPLETE:State.WAITING_FOR_INPUT,reason,outputs,details);}
}
